node --input-type=module - <<'NODE'
import fs from 'node:fs';
import {parse,stringify} from 'smol-toml';
import {pilotMcpEnvVars,installPilotShims,preflightPilot} from './scripts/pilot-support.mjs';
const base='/private/tmp/dip-automatic-pilot-20261028';
const configPath=base+'/user/.codex/config.toml';
fs.copyFileSync(configPath,base+'/user/.codex/config.before-mcp-fix.toml');
const config=parse(fs.readFileSync(configPath,'utf8'));
config.mcp_servers.dip.env_vars=pilotMcpEnvVars;
fs.writeFileSync(configPath,stringify(config));
installPilotShims(base);
const env={...process.env,DIP_USER_HOME:base+'/user',GIT_CONFIG_GLOBAL:base+'/gitconfig',GIT_CONFIG_NOSYSTEM:'1',GIT_TRACE2_EVENT:'0'};
for(const k of Object.keys(env))if(/^GIT_CONFIG_(COUNT|KEY_|VALUE_)/.test(k))delete env[k];
const receipt=await preflightPilot(base,config,env);
fs.writeFileSync(base+'/preflight-after-fix.json',JSON.stringify(receipt,null,2)+'\n');
console.log(JSON.stringify(receipt));
